import csv,json,math,itertools,statistics as st,bisect,pathlib
S=json.load(open(\"evaluation/pilot/witness-v4/specs-a.json\"))
def read(p,n):
 with open(p/n,newline=\"\") as f:return list(csv.DictReader(f,delimiter=\"\\t\" if n.endswith(\"tsv\") else \",\"))
def bc(a,b):return sum(abs(x-y) for x,y in zip(a,b))/(sum(a)+sum(b))
def mb(x):return st.mean(bc(a,b) for a,b in itertools.combinations(x,2))
def perm(x,g):
 n=len(x); pairs=list(itertools.combinations(range(n),2)); ds={(i,j):bc(x[i],x[j])**2 for i,j in pairs}; t=sum(ds.values())/n; w=sum(sum(ds[i,j] for i,j in pairs if g[i]==z and g[j]==z)/g.count(z) for z in set(g)); return (t-w)/(len(set(g))-1)/(w/(n-len(set(g)))),(t-w)/t
out=[]
for s in S:
 p=pathlib.Path(s[\"materials\"]); typ=s[\"item\"].split(\"/\")[1][:3]
 if typ==\"P01\":
  r=read(p,\"counts.tsv\"); x=[[float(a[c]) for a in r] for c in list(r[0])[1:]]; x=[a for a in x if sum(a)]; d={\"mean_bray_curtis\":mb(x),\"n_samples\":len(x)}
 elif typ==\"P02\":
  r=read(p,\"counts.tsv\"); z={a[\"station_id\"].replace(\"-\",\"\"):a[\"zone\"] for a in read(p,\"stations.csv\")}; x=[[float(v) for k,v in a.items() if k"'!="sample"] for a in r]; g=[z[a["sample"].replace("-","")] for a in r]; f,q=perm(x,g); d={"n":len(x),"pseudo_f":f,"r_squared":q}
 elif typ=="P03":
  r=read(p,"counts.tsv"); m={a["sample_id"]:a for a in read(p,"samples.csv")}; x=[]
  for a in r:
   b=m[a["sample"]]; vals=[float(v) for k,v in a.items() if k!="sample"]; x.append([round(v*int(b["n_counted"])/100) for v in vals] if b["value_type"]=="relative (%)" else vals)
  d={"mean_bray_curtis":mb(x)}
 elif typ=="P04":
  coarse=read(p,"counts_gt150.tsv"); fine={a["taxon"]:a for a in read(p,"counts_63_150.tsv")}; cores=read(p,"cores.csv"); picked={a["core_id"] for a in read(p,"picking.csv") if a["fraction_um"]=="63-150" and a["status"]=="picked in full"}; full=all(a["core_id"] in picked for a in cores); vals={2017:[],2021:[]}
  for a in cores:
   c=a["core_id"]; v=[float(b[c])+(float(fine[b["taxon"]][c]) if full else 0) for b in coarse]; n=sum(v); vals[int(a["campaign"])].append(-sum((t/n)*math.log(t/n) for t in v if t))
  d={"shannon_mean_2017":st.mean(vals[2017]),"shannon_mean_2021":st.mean(vals[2021])}
 elif typ=="P05":
  r=read(p,"counts.tsv"); tx={a["name_as_recorded"]:a["accepted_name"] for a in read(p,"taxonomy.csv")}; cols=list(r[0])[1:]; names=list(dict.fromkeys(tx[c] for c in cols)); x=[[sum(float(a[c]) for c in cols if tx[c]==name) for name in names] for a in r]; d={"mean_bray_curtis":mb(x),"richness":sum(any(a[i]!=0 for a in x) for i in range(len(names)))}
 elif typ=="P06":
  r=read(p,"counts.tsv"); reg={a["lab_number"]:a["core_id"] for a in read(p,"register.csv")}; z={a["core_id"]:a["zone"] for a in read(p,"cores.csv")}; coll={}
  for a in r:
   c=reg[a["lab_number"]]; v=[float(t) for k,t in a.items() if k!="lab_number"]; coll[c]=[i+j for i,j in zip(coll.get(c,[0]*len(v)),v)]
  x=[[v/sum(a) for v in a] for a in coll.values()]; g=[z[c] for c in coll]; f,q=perm(x,g); d={"n":len(x),"pseudo_f":f,"r_squared":q}
 elif typ=="P07":
  u={a["observer"]:a["unit_recorded"] for a in read(p,"observers.csv")}; r=read(p,"shells.csv"); x=[float(a["length"])*(10 if u[a["observer"]]=="cm" else 1) for a in r]; y=[float(a["width"])*(10 if u[a["observer"]]=="cm" else 1) for a in r]; lx=list(map(math.log10,x)); ly=list(map(math.log10,y)); cov=sum((a-st.mean(lx))*(b-st.mean(ly)) for a,b in zip(lx,ly)); slope=(1 if cov>0 else -1)*st.stdev(ly)/st.stdev(lx); d={"intercept":st.mean(ly)-slope*st.mean(lx),"mean_length_mm":st.mean(x),"n":len(x),"slope":slope}
 elif typ=="P08":
  dates=sorted((float(a["depth_cm"]),float(a["age_cal_bp"])) for a in read(p,"dates.csv") if a["status"]=="accepted"); depths=[a[0] for a in dates]; samples={a["sample_id"]:float(a["depth_cm"]) for a in read(p,"samples.csv")}; x=[]
  for a in read(p,"counts.tsv"):
   depth=samples[a["sample"]]; i=max(0,min(len(dates)-2,bisect.bisect_right(depths,depth)-1)); x0,y0=dates[i]; x1,y1=dates[i+1]; age=y0+(depth-x0)*(y1-y0)/(x1-x0)
   if age<11700:
    v=[float(t) for k,t in a.items() if k!="sample"]; x.append([t/sum(v) for t in v])
  d={"mean_bray_curtis":mb(x),"n_holocene":len(x)}
 assert list(d)==s["report_fields"]; out.append({"item":s["item"],"results":[{"name":k,"value":v} for k,v in d.items()],"notes":""})
print(json.dumps({"items":out},indent=2))
'"'"

